package com.abluepoint.summer.sample.invitation;

import com.abluepoint.summer.common.response.api.ApiError;
import com.abluepoint.summer.common.response.api.ApiResponse;
import com.abluepoint.summer.mvc.response.api.RawResponse;
import com.abluepoint.summer.mvc.request.api.RequestIdAccessor;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.http.*;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
class InvitationController {
    private final InvitationService service; private final RequestIdAccessor requestId;
    InvitationController(InvitationService service, RequestIdAccessor requestId) { this.service = service; this.requestId = requestId; }

    @PostMapping(value="/api/v1/enterprises/{enterpriseId}/invitations", consumes=MediaType.APPLICATION_JSON_VALUE)
    @PreAuthorize("hasAuthority('SCOPE_enterprise.invitation.write')") @RawResponse
    ResponseEntity<ApiResponse<InvitationIssue>> create(@PathVariable String enterpriseId,@RequestBody InvitationCreateRequest body,@RequestHeader(value="Idempotency-Key",required=false) String key,Authentication auth) { try { InvitationIssue result = service.create(enterpriseId,body,key,rid(),auth); return entity(HttpStatus.CREATED, result, result.revision()); } catch (InvitationIdempotencyConflictException e){return fail(HttpStatus.CONFLICT,"SUMMER_IDEMPOTENCY_CONFLICT",e.getMessage());} catch (InvitationValidationException e){return fail(HttpStatus.BAD_REQUEST,"SUMMER_INVITATION_INVALID",e.getMessage());} }

    @GetMapping("/api/v1/enterprises/{enterpriseId}/invitations/{invitationId}") @PreAuthorize("hasAuthority('SCOPE_enterprise.invitation.read')") @RawResponse
    ResponseEntity<ApiResponse<InvitationView>> get(@PathVariable String enterpriseId,@PathVariable String invitationId,Authentication auth,HttpServletRequest req){ try{InvitationView result=service.get(enterpriseId,invitationId,auth);return entity(HttpStatus.OK,result,result.revision(),req);}catch(InvitationConflictException e){return fail(HttpStatus.NOT_FOUND,"SUMMER_NOT_FOUND",e.getMessage());} }
    @GetMapping("/api/v1/enterprises/{enterpriseId}/invitations") @PreAuthorize("hasAuthority('SCOPE_enterprise.invitation.read')") @RawResponse
    ResponseEntity<ApiResponse<InvitationService.Page<InvitationView>>> list(@PathVariable String enterpriseId,@RequestParam(required=false) String search,@RequestParam(required=false) String status,@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="20") int pageSize,Authentication auth){try{return ok(service.listInvitations(enterpriseId,search,status,page,pageSize,auth));}catch(Exception e){return fail(HttpStatus.FORBIDDEN,"SUMMER_FORBIDDEN",e.getMessage());}}
    @GetMapping("/api/v1/enterprises/{enterpriseId}/invitations/{invitationId}/audit") @PreAuthorize("hasAuthority('SCOPE_enterprise.invitation.read')") @RawResponse
    ResponseEntity<ApiResponse<List<InvitationService.AuditEvent>>> audit(@PathVariable String enterpriseId,@PathVariable String invitationId,Authentication auth){try{return ok(service.audit(enterpriseId,invitationId,auth));}catch(InvitationConflictException e){return fail(HttpStatus.NOT_FOUND,"SUMMER_NOT_FOUND",e.getMessage());}}

    @PostMapping("/api/v1/enterprises/{enterpriseId}/invitations/{invitationId}:resend") @PreAuthorize("hasAuthority('SCOPE_enterprise.invitation.write')") @RawResponse
    ResponseEntity<ApiResponse<InvitationIssue>> resend(@PathVariable String enterpriseId,@PathVariable String invitationId,@RequestHeader(value="If-Match",required=false) String etag,@RequestHeader(value="Idempotency-Key",required=false) String key,Authentication auth){try{InvitationIssue r=service.resend(enterpriseId,invitationId,etag,key,rid(),auth);return entity(HttpStatus.OK,r,r.revision());}catch(InvitationPreconditionException e){return fail(HttpStatus.PRECONDITION_FAILED,"SUMMER_PRECONDITION_FAILED","The resource has changed");}catch(InvitationConflictException e){return fail(HttpStatus.CONFLICT,"SUMMER_INVITATION_UNUSABLE",e.getMessage());}catch(InvitationIdempotencyConflictException e){return fail(HttpStatus.CONFLICT,"SUMMER_IDEMPOTENCY_CONFLICT",e.getMessage());}}
    @PostMapping("/api/v1/enterprises/{enterpriseId}/invitations/{invitationId}:revoke") @PreAuthorize("hasAuthority('SCOPE_enterprise.invitation.write')") @RawResponse
    ResponseEntity<ApiResponse<InvitationView>> revoke(@PathVariable String enterpriseId,@PathVariable String invitationId,@RequestHeader(value="If-Match",required=false) String etag,@RequestHeader(value="Idempotency-Key",required=false) String key,Authentication auth){try{InvitationView result=service.revoke(enterpriseId,invitationId,etag,key,rid(),auth);return entity(HttpStatus.OK,result,result.revision());}catch(InvitationPreconditionException e){return fail(HttpStatus.PRECONDITION_FAILED,"SUMMER_PRECONDITION_FAILED","The resource has changed");}catch(InvitationConflictException e){return fail(HttpStatus.CONFLICT,"SUMMER_INVITATION_UNUSABLE",e.getMessage());}catch(InvitationIdempotencyConflictException e){return fail(HttpStatus.CONFLICT,"SUMMER_IDEMPOTENCY_CONFLICT",e.getMessage());}}

    @PostMapping("/api/v1/invitations/{token}:accept") @PreAuthorize("hasAuthority('SCOPE_enterprise.invitation.accept')") @RawResponse
    ResponseEntity<ApiResponse<InvitationView>> accept(@PathVariable String token,@RequestBody(required=false) InvitationContextRequest body,@RequestHeader(value="Idempotency-Key",required=false) String key,Authentication auth){try{return ok(service.accept(token,body,key,rid(),auth));}catch(InvitationContextMismatchException e){return fail(HttpStatus.CONFLICT,"SUMMER_INVITATION_CONTEXT_MISMATCH",e.getMessage());}catch(InvitationConflictException e){return fail(HttpStatus.CONFLICT,"SUMMER_INVITATION_UNUSABLE",e.getMessage());}catch(InvitationIdempotencyConflictException e){return fail(HttpStatus.CONFLICT,"SUMMER_IDEMPOTENCY_CONFLICT",e.getMessage());}}
    @PostMapping("/api/v1/invitations/{token}:reject") @PreAuthorize("hasAuthority('SCOPE_enterprise.invitation.accept')") @RawResponse
    ResponseEntity<ApiResponse<InvitationView>> rejectToken(@PathVariable String token,@RequestBody(required=false) InvitationContextRequest body,@RequestHeader(value="Idempotency-Key",required=false) String key,Authentication auth){try{return ok(service.reject(token,body,key,rid(),auth));}catch(InvitationContextMismatchException e){return fail(HttpStatus.CONFLICT,"SUMMER_INVITATION_CONTEXT_MISMATCH",e.getMessage());}catch(InvitationConflictException e){return fail(HttpStatus.CONFLICT,"SUMMER_INVITATION_UNUSABLE",e.getMessage());}catch(InvitationIdempotencyConflictException e){return fail(HttpStatus.CONFLICT,"SUMMER_IDEMPOTENCY_CONFLICT",e.getMessage());}}

    @PostMapping(value="/api/v1/enterprises/{enterpriseId}/join-applications", consumes=MediaType.APPLICATION_JSON_VALUE) @PreAuthorize("hasAuthority('SCOPE_enterprise.join-application.submit')") @RawResponse
    ResponseEntity<ApiResponse<JoinApplicationView>> submit(@PathVariable String enterpriseId,@RequestBody JoinApplicationSubmitRequest body,@RequestHeader(value="Idempotency-Key",required=false) String key,Authentication auth){try{JoinApplicationView r=service.submit(enterpriseId,body,key,rid(),auth);return entity(HttpStatus.CREATED,r,r.revision());}catch(InvitationValidationException e){return fail(HttpStatus.BAD_REQUEST,"SUMMER_INVITATION_INVALID",e.getMessage());}catch(InvitationIdempotencyConflictException e){return fail(HttpStatus.CONFLICT,"SUMMER_IDEMPOTENCY_CONFLICT",e.getMessage());}}
    @PatchMapping(value="/api/v1/enterprises/{enterpriseId}/join-applications/{id}", consumes=MediaType.APPLICATION_JSON_VALUE) @PreAuthorize("hasAuthority('SCOPE_enterprise.join-application.submit')") @RawResponse
    ResponseEntity<ApiResponse<JoinApplicationView>> supplement(@PathVariable String enterpriseId,@PathVariable String id,@RequestBody JoinApplicationSupplementRequest body,@RequestHeader(value="If-Match",required=false) String etag,@RequestHeader(value="Idempotency-Key",required=false) String key,Authentication auth){try{JoinApplicationView r=service.supplement(enterpriseId,id,body,etag,key,rid(),auth);return entity(HttpStatus.OK,r,r.revision());}catch(InvitationPreconditionException e){return fail(HttpStatus.PRECONDITION_FAILED,"SUMMER_PRECONDITION_FAILED","The resource has changed");}catch(JoinApplicationConflictException e){return fail(HttpStatus.CONFLICT,"SUMMER_JOIN_APPLICATION_CONFLICT",e.getMessage());}catch(InvitationIdempotencyConflictException e){return fail(HttpStatus.CONFLICT,"SUMMER_IDEMPOTENCY_CONFLICT",e.getMessage());}}
    @PostMapping("/api/v1/enterprises/{enterpriseId}/join-applications/{id}:approve") @PreAuthorize("hasAuthority('SCOPE_enterprise.join-application.review')") @RawResponse
    ResponseEntity<ApiResponse<JoinApplicationView>> approve(@PathVariable String enterpriseId,@PathVariable String id,@RequestHeader(value="If-Match",required=false) String etag,@RequestHeader(value="Idempotency-Key",required=false) String key,Authentication auth){try{JoinApplicationView r=service.approve(enterpriseId,id,etag,key,rid(),auth);return entity(HttpStatus.OK,r,r.revision());}catch(InvitationPreconditionException e){return fail(HttpStatus.PRECONDITION_FAILED,"SUMMER_PRECONDITION_FAILED","The resource has changed");}catch(JoinApplicationConflictException e){return fail(HttpStatus.CONFLICT,"SUMMER_JOIN_APPLICATION_CONFLICT",e.getMessage());}catch(InvitationIdempotencyConflictException e){return fail(HttpStatus.CONFLICT,"SUMMER_IDEMPOTENCY_CONFLICT",e.getMessage());}}
    @PostMapping("/api/v1/enterprises/{enterpriseId}/join-applications/{id}:reject") @PreAuthorize("hasAuthority('SCOPE_enterprise.join-application.review')") @RawResponse
    ResponseEntity<ApiResponse<JoinApplicationView>> reject(@PathVariable String enterpriseId,@PathVariable String id,@RequestHeader(value="If-Match",required=false) String etag,@RequestHeader(value="Idempotency-Key",required=false) String key,Authentication auth){try{return entity(HttpStatus.OK,service.reject(enterpriseId,id,etag,key,rid(),auth),etag);}catch(InvitationPreconditionException e){return fail(HttpStatus.PRECONDITION_FAILED,"SUMMER_PRECONDITION_FAILED","The resource has changed");}catch(JoinApplicationConflictException e){return fail(HttpStatus.CONFLICT,"SUMMER_JOIN_APPLICATION_CONFLICT",e.getMessage());}catch(InvitationIdempotencyConflictException e){return fail(HttpStatus.CONFLICT,"SUMMER_IDEMPOTENCY_CONFLICT",e.getMessage());}}
    @PostMapping("/api/v1/enterprises/{enterpriseId}/join-applications/{id}:withdraw") @PreAuthorize("hasAuthority('SCOPE_enterprise.join-application.submit')") @RawResponse
    ResponseEntity<ApiResponse<JoinApplicationView>> withdraw(@PathVariable String enterpriseId,@PathVariable String id,@RequestHeader(value="If-Match",required=false) String etag,@RequestHeader(value="Idempotency-Key",required=false) String key,Authentication auth){try{JoinApplicationView r=service.withdraw(enterpriseId,id,etag,key,rid(),auth);return entity(HttpStatus.OK,r,r.revision());}catch(InvitationPreconditionException e){return fail(HttpStatus.PRECONDITION_FAILED,"SUMMER_PRECONDITION_FAILED","The resource has changed");}catch(JoinApplicationConflictException e){return fail(HttpStatus.CONFLICT,"SUMMER_JOIN_APPLICATION_CONFLICT",e.getMessage());}catch(InvitationIdempotencyConflictException e){return fail(HttpStatus.CONFLICT,"SUMMER_IDEMPOTENCY_CONFLICT",e.getMessage());}}
    @GetMapping("/api/v1/enterprises/{enterpriseId}/join-applications/{id}/audit") @PreAuthorize("hasAuthority('SCOPE_enterprise.join-application.read')") @RawResponse
    ResponseEntity<ApiResponse<List<InvitationService.AuditEvent>>> appAudit(@PathVariable String enterpriseId,@PathVariable String id,Authentication auth){try{return ok(service.applicationAudit(enterpriseId,id,auth));}catch(JoinApplicationConflictException e){return fail(HttpStatus.NOT_FOUND,"SUMMER_NOT_FOUND",e.getMessage());}}
    @GetMapping("/api/v1/enterprises/{enterpriseId}/join-applications") @PreAuthorize("hasAuthority('SCOPE_enterprise.join-application.read')") @RawResponse
    ResponseEntity<ApiResponse<InvitationService.Page<JoinApplicationView>>> applications(@PathVariable String enterpriseId,@RequestParam(required=false) String search,@RequestParam(required=false) String status,@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="20") int pageSize,Authentication auth){try{return ok(service.listApplications(enterpriseId,search,status,page,pageSize,auth));}catch(Exception e){return fail(HttpStatus.FORBIDDEN,"SUMMER_FORBIDDEN",e.getMessage());}}

    private String rid(){return requestId.currentRequestId();}
    private <T> ResponseEntity<ApiResponse<T>> ok(T data){return ResponseEntity.ok().header("X-Request-Id",rid()).body(ApiResponse.success(data,rid()));}
    private <T> ResponseEntity<ApiResponse<T>> entity(HttpStatus status,T data,String revision){return ResponseEntity.status(status).eTag("\""+revision+"\"").header("X-Request-Id",rid()).body(ApiResponse.success(data,rid()));}
    private <T> ResponseEntity<ApiResponse<T>> entity(HttpStatus status,T data,String revision,HttpServletRequest req){String e="\""+revision+"\"";if(e.equals(req.getHeader(HttpHeaders.IF_NONE_MATCH)))return ResponseEntity.status(HttpStatus.NOT_MODIFIED).eTag(e).header("X-Request-Id",rid()).build();return entity(status,data,revision);}
    private <T> ResponseEntity<ApiResponse<T>> fail(HttpStatus status,String code,String message){return ResponseEntity.status(status).header("X-Request-Id",rid()).body(ApiResponse.failure(new ApiError(code,message,List.of()),rid()));}
}
